    visit card_url(cards(:logo))
    within "#comment_..." do
      click_on "Add a reaction"  # or find(".reactions__trigger")
      fill_in "reaction_content", with: "👍"
      click_on "React"  # confirm
      assert_selector ".reaction", text: "👍"
