  display: inline-flex; flex-wrap: wrap; gap: var(--inline-space-half);
  &:not(:has(.reaction)) { display: none; }
}
```

```
.reaction {
  --btn-size: 100%; --reaction-hover-brightness: 0.9;
  align-items: center; background-color: canvas; block-size: var(--reaction-size);
  border: 1px solid var(--reaction-border-color); border-radius: 4rem;
  display: inline-flex; gap: 0.25ch; max-inline-size: 100%; opacity: 1;
  padding: 0.1em 0.36em 0.1em 0.12em; position: relative;
  transition: opacity/transform;
  &:has(span.txt-small.txt-medium) { /* emoji only reactions */ padding: 0.1em 0.12em; }
  .btn { font-size: 0.6em; inline-size: auto; }
