        const found = [];
        for (const sheet of document.styleSheets) {
          let list = [];
          try { list = sheet.cssRules } catch (e) { continue }
          const walk = (rules) => {
            for (const r of rules) {
              if (r.cssText && r.cssText.includes("reaction__delete")) found.push(r.cssText);
              if (r.cssRules) walk(r.cssRules);
            }
          };
          walk(list);
        }
        return found;
      })()
